    let child_source =
        "<script lang=\"ts\">\nconst internalOnly = true;\n</script>\n<p>empty</p>\n";
    let zero_prop_source = "<script lang=\"ts\">\nimport EmptyChild from './EmptyChild.svelte';\n</script>\n<EmptyChild ";
